FUNCTION_BLOCK FB_Duplex
VAR_INPUT
    demanda : BOOL; (* Demanda de arranque *)
    falla1 : BOOL; (* Falla de la bomba 1 *)
    falla2 : BOOL; (* Falla de la bomba 2 *)
END_VAR
VAR_OUTPUT
    bomba1 : BOOL; (* Bomba principal *)
    bomba2 : BOOL; (* Bomba de respaldo *)
    almFalla : BOOL; (* Alarma de falla de la bomba principal *)
END_VAR
VAR
    estado : INT := 0; (* Estado actual: 0 = detenido, 1 = bomba1 principal, 2 = bomba2 principal *)
    demandaAnterior : BOOL := FALSE; (* Estado anterior de la demanda *)
END_VAR

(* Control de la alternancia de bombas y manejo de fallas *)
IF demanda THEN
    IF NOT demandaAnterior THEN
        (* Transición de FALSE a TRUE en demanda *)
        estado := (estado + 1) MOD 3;
        IF estado = 0 THEN
            estado := 1; (* Asegura que la primera demanda arranque bomba1 *)
        END_IF
    END_IF

    CASE estado OF
        1:
            IF falla1 THEN
                bomba1 := FALSE;
                bomba2 := NOT falla2;
                almFalla := NOT falla2;
            ELSE
                bomba1 := TRUE;
                bomba2 := FALSE;
                almFalla := FALSE;
            END_IF
        2:
            IF falla2 THEN
                bomba2 := FALSE;
                bomba1 := NOT falla1;
                almFalla := NOT falla1;
            ELSE
                bomba2 := TRUE;
                bomba1 := FALSE;
                almFalla := FALSE;
            END_IF
    END_CASE
ELSE
    bomba1 := FALSE;
    bomba2 := FALSE;
    almFalla := FALSE;
END_IF

(* Actualización del estado anterior de la demanda *)
demandaAnterior := demanda;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Duplex
VAR_INPUT
    demanda : BOOL;   // Entrada de demanda
    falla1 : BOOL;    // Falla de la bomba 1
    falla2 : BOOL;    // Falla de la bomba 2
END_VAR

VAR_OUTPUT
    bomba1 : BOOL;    // Salida para controlar la bomba 1
    bomba2 : BOOL;    // Salida para controlar la bomba 2
    almFalla : BOOL;  // Alarma de falla
END_VAR

VAR
    principal : BOOL; // Indica cuál es la bomba principal (TRUE para bomba1, FALSE para bomba2)
    lastDemanda : BOOL; // Estado anterior de la demanda
END_VAR

// Inicialización
IF NOT demanda AND NOT lastDemanda THEN
    principal := TRUE; // Inicialmente, bomba1 es la principal
END_IF

// Alternancia de bombas
IF demanda AND NOT lastDemanda THEN
    principal := NOT principal; // Alternar la bomba principal en cada nueva demanda
END_IF

// Lógica de control de bombas
IF demanda THEN
    IF principal THEN
        IF NOT falla1 THEN
            bomba1 := TRUE;
            bomba2 := FALSE;
            almFalla := FALSE;
        ELSIF NOT falla2 THEN
            bomba1 := FALSE;
            bomba2 := TRUE;
            almFalla := TRUE;
        ELSE
            bomba1 := FALSE;
            bomba2 := FALSE;
            almFalla := TRUE;
        END_IF
    ELSE
        IF NOT falla2 THEN
            bomba1 := FALSE;
            bomba2 := TRUE;
            almFalla := FALSE;
        ELSIF NOT falla1 THEN
            bomba1 := TRUE;
            bomba2 := FALSE;
            almFalla := TRUE;
        ELSE
            bomba1 := FALSE;
            bomba2 := FALSE;
            almFalla := TRUE;
        END_IF
    END_IF
ELSE
    bomba1 := FALSE;
    bomba2 := FALSE;
    almFalla := FALSE;
END_IF

// Actualizar el estado anterior de la demanda
lastDemanda := demanda;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Llenado
VAR_INPUT
    nivelAlto, nivelBajo, btnInicio, btnParo : BOOL;
END_VAR

VAR_OUTPUT
    vLlenado, motorMezcla, vDescarga : BOOL;
END_VAR

VAR
    estado : INT := 0; // 0: reposo, 1: llenado, 2: mezcla, 3: descarga
    timerMezcla : TON;
END_VAR

// Estado de reposo
IF btnParo THEN
    estado := 0;
    vLlenado := FALSE;
    motorMezcla := FALSE;
    vDescarga := FALSE;
    timerMezcla(IN := FALSE);
ELSIF btnInicio AND estado = 0 THEN
    estado := 1;
    vLlenado := TRUE;
END_IF

// Estado de llenado
IF estado = 1 THEN
    IF nivelAlto THEN
        estado := 2;
        vLlenado := FALSE;
        motorMezcla := TRUE;
        timerMezcla(IN := TRUE, PT := T#60S);
    END_IF
END_IF

// Estado de mezcla
IF estado = 2 THEN
    IF timerMezcla.Q THEN
        estado := 3;
        motorMezcla := FALSE;
        vDescarga := TRUE;
    END_IF
END_IF

// Estado de descarga
IF estado = 3 THEN
    IF nivelBajo THEN
        estado := 0;
        vDescarga := FALSE;
    END_IF
END_IF

FUNCTION_BLOCK FB_Duplex
VAR_INPUT
    demanda : BOOL; (* Señal de demanda de bombeo *)
    falla1  : BOOL; (* Falla de bomba 1 *)
    falla2  : BOOL; (* Falla de bomba 2 *)
END_VAR
VAR_OUTPUT
    bomba1   : BOOL; (* Salida de bomba 1 *)
    bomba2   : BOOL; (* Salida de bomba 2 *)
    almFalla : BOOL; (* Alarma de falla en bomba principal *)
END_VAR
VAR
    principal1   : BOOL := TRUE;  (* TRUE = bomba1 es principal, FALSE = bomba2 es principal *)
    demandaAntes : BOOL := FALSE; (* Valor de demanda en el ciclo anterior, para detectar flanco *)
    flancoSubida : BOOL;          (* Flanco de subida de demanda *)
END_VAR

(* Detectar flanco de subida de demanda *)
flancoSubida := demanda AND NOT demandaAntes;

(* En cada flanco de subida se alterna la bomba principal *)
IF flancoSubida THEN
    principal1 := NOT principal1;
END_IF;

(* Lógica de control con demanda activa *)
IF demanda THEN
    IF principal1 THEN
        (* Bomba 1 es la principal *)
        IF NOT falla1 THEN
            (* Principal sin falla: funciona bomba 1 *)
            bomba1   := TRUE;
            bomba2   := FALSE;
            almFalla := FALSE;
        ELSIF NOT falla2 THEN
            (* Principal con falla, respaldo sin falla: funciona bomba 2 *)
            bomba1   := FALSE;
            bomba2   := TRUE;
            almFalla := TRUE;
        ELSE
            (* Ambas con falla: ninguna funciona *)
            bomba1   := FALSE;
            bomba2   := FALSE;
            almFalla := TRUE;
        END_IF;
    ELSE
        (* Bomba 2 es la principal *)
        IF NOT falla2 THEN
            (* Principal sin falla: funciona bomba 2 *)
            bomba1   := FALSE;
            bomba2   := TRUE;
            almFalla := FALSE;
        ELSIF NOT falla1 THEN
            (* Principal con falla, respaldo sin falla: funciona bomba 1 *)
            bomba1   := TRUE;
            bomba2   := FALSE;
            almFalla := TRUE;
        ELSE
            (* Ambas con falla: ninguna funciona *)
            bomba1   := FALSE;
            bomba2   := FALSE;
            almFalla := TRUE;
        END_IF;
    END_IF;
ELSE
    (* Sin demanda: ambas bombas detenidas, sin alarma *)
    bomba1   := FALSE;
    bomba2   := FALSE;
    almFalla := FALSE;
END_IF;

(* Guardar estado de demanda para el próximo ciclo *)
demandaAntes := demanda;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Llenado
VAR_INPUT
    nivelAlto : BOOL; (* Sensor de nivel alto *)
    nivelBajo : BOOL; (* Sensor de nivel bajo *)
    btnInicio : BOOL; (* Botón de inicio del proceso *)
    btnParo : BOOL;   (* Botón de paro del proceso *)
END_VAR
VAR_OUTPUT
    vLlenado : BOOL;  (* Válvula de llenado *)
    motorMezcla : BOOL; (* Motor de mezcla *)
    vDescarga : BOOL; (* Válvula de descarga *)
END_VAR
VAR
    estado : INT := 0; (* Estado del proceso *)
    tMezcla : TON;     (* Temporizador para el motor de mezcla *)
END_VAR

(* Lógica del proceso de llenado por etapas *)
IF btnParo THEN
    (* Si se presiona el botón de paro, detener todo y volver a reposo *)
    estado := 0;
    vLlenado := FALSE;
    motorMezcla := FALSE;
    vDescarga := FALSE;
ELSE
    CASE estado OF
        0: (* Estado de reposo *)
            IF btnInicio THEN
                estado := 1; (* Iniciar proceso de llenado *)
            END_IF;
        1: (* Llenado *)
            vLlenado := TRUE;
            IF nivelAlto THEN
                vLlenado := FALSE;
                estado := 2; (* Pasar al estado de mezcla *)
                tMezcla(IN := TRUE, PT := T#60S); (* Iniciar temporizador de mezcla *)
            END_IF;
        2: (* Mezcla *)
            motorMezcla := TRUE;
            IF tMezcla.Q THEN
                motorMezcla := FALSE;
                estado := 3; (* Pasar al estado de descarga *)
            END_IF;
        3: (* Descarga *)
            vDescarga := TRUE;
            IF nivelBajo THEN
                vDescarga := FALSE;
                estado := 0; (* Volver al estado de reposo *)
            END_IF;
    END_CASE;
END_IF;
END_FUNCTION_BLOCK
